result *insert_unique(result *out, tree *self, void *const *value) {
 node *y=self->header,*x=y->parent; bool comp=true;
 while(x){y=x;comp=*value<x->value;x=comp?x->left:x->right;}
 node*j=y;
 if(comp){if(j==self->header->left){out->position=tree_insert(self,x,y,value);out->inserted=true;return out;}if(j->left){j=j->left;while(j->right)j=j->right;}else{node*p=j->parent;while(j==p->left){j=p;p=p->parent;}j=p;}}
 if(j->value<*value){out->position=tree_insert(self,x,y,value);out->inserted=true;}else{out->position=j;out->inserted=false;}return out;
